css:
/* Page margins (Print Format): top 18 mm, left 25 mm, right 20 mm; the head adds 27 mm, so the sender line
   and address field start 45 mm from the top (DIN 5008 form B). */
.print-format { font-family: Inter, "Helvetica Neue", Arial, sans-serif; font-size: 10pt; color: #171717; padding: 0 !important; }
.eo-head { margin-top: 27mm; width: 100%; display: table; table-layout: fixed; }
.eo-address, .eo-info { display: table-cell; vertical-align: top; }
.eo-address { width: 85mm; padding-right: 10mm; min-height: 45mm; }
.eo-sender { margin: 0 0 2mm; padding-bottom: 0.5mm; border-bottom: 0.2mm solid #b5b5b5; color: #6b6b6b; font-size: 7pt; }
.eo-address address { font-style: normal; line-height: 1.45; }
.eo-info { font-size: 9pt; }
.eo-info th { padding: 0 4mm 0.8mm 0; color: #6b6b6b; font-weight: normal; text-align: left; white-space: nowrap; vertical-align: top; }
.eo-info td { padding: 0 0 0.8mm; word-break: break-word; }
.eo-subject { margin: 18mm 0 6mm; font-size: 12pt; font-weight: 700; }
.eo-items { width: 100%; border-collapse: collapse; font-size: 9.5pt; }
.eo-items th { padding: 1.5mm; border-bottom: 0.3mm solid #171717; text-align: left; font-size: 9pt; font-weight: 600; }
.eo-items td { padding: 1.5mm; border-bottom: 0.2mm solid #e0e0e0; vertical-align: top; }
.eo-items th:first-child, .eo-items td:first-child { width: 10mm; }
.eo-items th:nth-child(n+3), .eo-items .eo-num { text-align: right; white-space: nowrap; }
.eo-items tfoot td { border: 0; padding: 0.8mm 1.5mm; text-align: right; }
.eo-items tfoot tr:first-child td { padding-top: 3mm; }
.eo-items .eo-total td { padding-top: 1.5mm; border-top: 0.3mm solid #171717; font-weight: 700; font-size: 10.5pt; }
.eo-note { margin: 6mm 0 0; }
.eo-footer { width: 100%; border-top: 0.2mm solid #b5b5b5; font-family: Inter, "Helvetica Neue", Arial, sans-serif; font-size: 7pt; color: #4a4a4a; }
.eo-footer td { padding: 1.5mm 3mm 0 0; vertical-align: top; line-height: 1.4; }

html:
{#- Ticket order from the website as a DIN 5008 letter (form B), like the review step of the ticket dialog
    (phamos/templates/web_profile/macros.html, .wp-invoice): sender line and address field 45 mm from the
    top on the left, information block on the right, subject, items, totals with VAT, payment, company
    footer. Data beyond the Sales Order: phamos.marketing.billing.event_order_print_context. -#}
{%- set ctx = event_order_print_context(doc) -%}
{%- set f = ctx.company -%}
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value, currency=doc.currency) }}{%- endmacro -%}
<div class="eo-sheet">
	<div class="eo-head">
		<div class="eo-address">
			{%- if ctx.sender %}<p class="eo-sender">{{ ctx.sender | e }}</p>{% endif %}
			<address>
				{%- for line in ctx.recipient %}{{ line | e }}<br>{% endfor %}
				{%- if doc.address_display %}{{ doc.address_display }}{% endif %}
				{%- if doc.tax_id %}<br>{{ _("VAT ID") }} {{ doc.tax_id | e }}{% endif -%}
			</address>
		</div>
		<table class="eo-info">
			<tr><th>{{ _("Order number") }}</th><td>{{ doc.name | e }}</td></tr>
			<tr><th>{{ _("Date") }}</th><td>{{ ctx.date | e }}</td></tr>
			{%- if ctx.event_date %}<tr><th>{{ _("Event date") }}</th><td>{{ ctx.event_date | e }}</td></tr>{% endif %}
			{%- if ctx.venue %}<tr><th>{{ _("Venue") }}</th><td>{{ ctx.venue | e }}</td></tr>{% endif %}
			{%- if doc.contact_email %}<tr><th>{{ _("Tickets to") }}</th><td>{{ doc.contact_email | e }}</td></tr>{% endif %}
		</table>
	</div>
	<h3 class="eo-subject">{{ _("Order: {0}").format((ctx.event_title or doc.name) | e) }}</h3>
	<table class="eo-items">
		<thead><tr><th>{{ _("Pos.") }}</th><th>{{ _("Description") }}</th><th>{{ _("Qty") }}</th><th>{{ _("Unit price") }}</th><th>{{ _("Amount") }}</th></tr></thead>
		<tbody>
			{%- for row in doc.items %}
			<tr><td>{{ row.idx }}</td><td>{{ (row.description or row.item_name) | striptags | e }}</td>
				<td class="eo-num">{{ row.qty | int if row.qty == row.qty | int else row.qty }}</td>
				<td class="eo-num">{{ money(row.rate) }}</td><td class="eo-num">{{ money(row.amount) }}</td></tr>
			{%- endfor %}
		</tbody>
		<tfoot>
			<tr><td colspan="4">{{ _("Net") }}</td><td class="eo-num">{{ money(doc.net_total) }}</td></tr>
			{%- for v in ctx.vat %}
			<tr><td colspan="4">{{ _("VAT {0} %").format(v.rate) }}</td><td class="eo-num">{{ money(v.amount) }}</td></tr>
			{%- endfor %}
			<tr class="eo-total"><td colspan="4">{{ _("Total") }}</td><td class="eo-num">{{ money(doc.rounded_total or doc.grand_total) }}</td></tr>
		</tfoot>
	</table>
	<p class="eo-note">{{ _("Payment by invoice, due within 14 days.") }}</p>
</div>
{%- if f.name %}
<div id="footer-html" class="visible-pdf">
	<table class="eo-footer"><tr>
		<td><strong>{{ f.name | e }}</strong>{% for line in f.address_lines %}<br>{{ line | e }}{% endfor %}</td>
		{%- if f.phone or f.email or f.website %}
		<td><strong>{{ _("Contact") }}</strong>
			{%- if f.phone %}<br>{{ f.phone | e }}{% endif %}
			{%- if f.email %}<br>{{ f.email | e }}{% endif %}
			{%- if f.website %}<br>{{ f.website | replace('https://', '') | replace('http://', '') | trim('/') | e }}{% endif %}</td>
		{%- endif %}
		{%- if f.register_lines or f.tax_id %}
		<td>{%- for line in f.register_lines %}{% if not loop.first %}<br>{% endif %}{{ line | e }}{% endfor %}
			{%- if f.tax_id %}{% if f.register_lines %}<br>{% endif %}{{ _("VAT ID") }}: {{ f.tax_id | e }}{% endif %}</td>
		{%- endif %}
		{%- if f.bank %}
		<td><strong>{{ f.bank.name | e }}</strong><br>IBAN: {{ f.bank.iban | e }}{% if f.bank.bic %}<br>BIC: {{ f.bank.bic | e }}{% endif %}</td>
		{%- endif %}
	</tr></table>
</div>
{%- endif %}
